insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('c95c564c-1c6f-4900-868e-6ac1b5554a50', NULL, 'choose_meaning', 'Mẫu ngữ pháp nào có nghĩa: "Muốn cái gì／Không muốn cái gì (mong muốn sở hữu 1 vật)"?', '何がほしいですか', 'Lượng từ（ngày, tiếng, đồng hồ...）に～回 + V', 'Dạng quá khứ của tính từ (A)', 'N + Trợ từ + Số đếm + Động từ', '何がほしいですか', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('c95c564c-1c6f-4900-868e-6ac1b5554a50', NULL, 'choose_connection', 'Cách nối đúng của mẫu "何がほしいですか" (Muốn cái gì／Không muốn cái gì (mong muốn sở hữu 1 vật)) là gì?', '何 + が + ほしいですか → （私は）N + が + ほしい／ほしくないです', 'Lượng từ(khoảng thời gian) + に + Số đếm + 回 + V', 'Lượng từ／N + だけ', 'どのぐらい／どのくらい + Vますか → N(khoảng thời gian) + ぐらい／くらい + Vます', '何 + が + ほしいですか → （私は）N + が + ほしい／ほしくないです', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('4f32f44d-f84a-4231-b479-7d0162632af7', NULL, 'fill_blank', 'Điền vào chỗ trống: 今、＿＿＿です。', NULL, NULL, NULL, NULL, '寝たい', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('4f32f44d-f84a-4231-b479-7d0162632af7', NULL, 'choose_meaning', 'Mẫu ngữ pháp nào có nghĩa: "Muốn làm gì／Không muốn làm gì"?', 'N + Trợ từ + Số đếm + Động từ', 'どのぐらい／どのくらい Vますか', 'V たいですか／何を（が）V たいですか', '何がほしいですか', 'V たいですか／何を（が）V たいですか', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('4f32f44d-f84a-4231-b479-7d0162632af7', NULL, 'choose_connection', 'Cách nối đúng của mẫu "V たいですか／何を（が）V たいですか" (Muốn làm gì／Không muốn làm gì) là gì?', 'Lượng từ(khoảng thời gian) + に + Số đếm + 回 + V', 'Aい → Aかったです (đã~) ／ Aい → Aくなかったです (đã không~) ； いい → よかったです／よくなかったです (bất quy tắc)', 'N(nhóm) + の中で + A(đối tượng) + が + 一番 + Adj + です', '（私は）N + を（が） + V(bỏ ます) + たいです', '（私は）N + を（が） + V(bỏ ます) + たいです', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('4f32f44d-f84a-4231-b479-7d0162632af7', NULL, 'reorder_sentence', 'Sắp xếp thành câu đúng: すし ／ が ／ 食べたい ／ です (Tôi muốn ăn sushi.)', NULL, NULL, NULL, NULL, 'すしが食べたいです', 'generated');
